Etapa 2: Análise e Consolidação por Planta

# Graos
graoseparar &lt;-
  graos |&gt;
  select(img, length, width)

graos_resumo &lt;- graoseparar |&gt;
  # Extrair o img numérico do início do nome da imagem
  mutate(img = str_extract(img, "^\\d+")) |&gt;

  # Agrupar os registros por planta
  group_by(img) |&gt;

  # Calcular as métricas de cada planta
  summarise(
    total_graos = n(),
    length = mean(length, na.rm = TRUE),
    width = mean(width, na.rm = TRUE),
    .groups = "drop"
    ) |&gt; 

# teste de visualização
  filter(width &lt; 0.35, width &gt; 0.1)

# renomear colunas de graos
    graos_resumo &lt;-
  graos_resumo |&gt;
  rename(ng = total_graos, cg = length, lg = width)

# Capsulas
capsulas_separar &lt;- 
  capsulas |&gt;
  select(img)

capsulas_resumo &lt;- 
  capsulas_separar |&gt; mutate(img = str_extract(img, "^\\d+")) |&gt;
 ## Agrupar os registros por planta
  group_by(img) |&gt;
   ## Calcular as métricas de cada planta
  summarise(
    total_capsulas = n())

## renomear coluna
capsulas_resumo &lt;-
  capsulas_resumo |&gt;
  rename(nc = total_capsulas)

# unificação dos valores de NG, GC, LC, NC

## Graos
graos_resumo &lt;- graos_resumo |&gt;
  mutate(img = as.numeric(img))

## Capsulas
capsulas_resumo &lt;- capsulas_resumo |&gt;
  mutate(img = as.numeric(img))

## Unificar colunas
laboratorio_final &lt;- laboratorio |&gt;
  left_join(graos_resumo, by = c("img" = "img")) |&gt;
  left_join(capsulas_resumo, by = c("img" = "img"))

Etapa 3: Análise e Consolidação por Genótipo

genotipos_resumo &lt;- laboratorio_final |&gt;
  group_by(gen, tipo) |&gt;
  summarise(
    np = n_distinct(img),
    across(
      where(is.numeric) & !any_of("img"),
      ~ mean(.x, na.rm = TRUE)
    ),
    .groups = "drop"
  )

# Juntar mmg no df de genótipos
genotipos_final &lt;- genotipos_resumo |&gt;
  left_join(mmg, by = c("gen", "tipo"))
